import { SparklesFilledSmall } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import classes from './ai-plus-button-scss.js';

type Props = { onClick: () => void; dataHook?: string };

export const AiPlusButton = React.forwardRef<HTMLButtonElement, Props>(
  ({ onClick, dataHook }, ref) => {
    return (
      <button
        ref={ref}
        type="button"
        className={classes.button}
        onClick={onClick}
        data-hook={dataHook}
        tabIndex={-1}
      >
        <SparklesFilledSmall fill="currentColor" />
      </button>
    );
  }
);
