import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';
import type { ToolbarItemProps } from './../../toolbars-v3/types.js';

import { AiIcon } from './ai-icon.js';
import classes from './toolbar-button-scss.js';

export const AiToolbarButton: React.FC<ToolbarItemProps & { showLabel?: boolean }> = ({
  toolbarItem,
  showLabel,
  dataHook,
}) => {
  const { t } = useContext(RicosContext);
  const tooltip = t(toolbarItem.presentation?.tooltip);

  return (
    <ToolbarButton
      className={classes.accentColor}
      prefix={AiIcon}
      // WDS suppresses the tooltip once a label is placed, so its text — which differs from
      // the label's — becomes the accessible name instead of being dropped.
      {...(showLabel
        ? { label: t('AIPlugin_ToolbarButton_Text'), ariaLabel: tooltip }
        : { tooltip })}
      active={toolbarItem.attributes.active}
      disabled={toolbarItem.attributes.disabled}
      onClick={e => toolbarItem.commands?.click?.(e)}
      // The toolbar injects `presentation.dataHook` only into the visible copy of each button,
      // not the hidden overflow-measurement one — forwarding it instead of hardcoding
      // TEXT_BUTTON_AI keeps e2e selectors off the duplicate.
      dataHook={dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
