import { ListItemSection } from '@wix/design-system';
import { EditSparklesSmall, ImageSparklesSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { EditorContext, ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import type { ModalService } from './../../ricos-modals/index.js';
import type { TiptapEditor } from './../../ricos-types/index.js';
import { DropdownModal } from './../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemDivider } from './../../_shared/list-item-divider/list-item-divider.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';
import { unreachable } from './../../_shared/uncreachable.js';

import {
  AI_FLOW_ITEM_CONTENT,
  AI_FLOW_ITEM_IMAGE,
  AI_FLOW_SELECTION_POPOVER,
} from '../data-hooks.js';
import type { AiPluginEditorConfig, FlowSelectionItem, Prompt } from '../types.js';
import { AI_FLOW_SELECTION_MODAL_ID } from '../types.js';

type AiFlowSelectionModalProps = {
  toggleAiContentModal: (
    editor: TiptapEditor,
    modalsService: ModalService,
    initialPrompt?: Prompt
  ) => void;
  toggleAiImageModal: (editor: TiptapEditor, modalsService: ModalService) => void;
  config: AiPluginEditorConfig;
};

export const AiFlowSelectionModal: React.FC<AiFlowSelectionModalProps> = ({
  toggleAiContentModal,
  toggleAiImageModal,
  config,
}) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const { adapter } = useContext(EditorContext);

  const closeModal = React.useCallback(() => {
    modalService.closeModal(AI_FLOW_SELECTION_MODAL_ID);
  }, [modalService]);

  const openAiContentModal = React.useCallback(
    (initialPrompt?: Prompt) => {
      toggleAiContentModal(adapter.tiptapEditor, modalService, initialPrompt);
    },
    [adapter.tiptapEditor, modalService]
  );

  const defaultFlowSelectionItems: FlowSelectionItem[] = React.useMemo(
    () => [
      {
        type: 'action',
        title: t('AIPlugin_Flow_ContentAssistant'),
        icon: EditSparklesSmall,
        onClick: () => toggleAiContentModal(adapter.tiptapEditor, modalService),
        dataHook: AI_FLOW_ITEM_CONTENT,
      },
      {
        type: 'action',
        title: t('AIPlugin_Flow_ImageGenerator'),
        icon: ImageSparklesSmall,
        onClick: () => toggleAiImageModal(adapter.tiptapEditor, modalService),
        dataHook: AI_FLOW_ITEM_IMAGE,
      },
    ],
    [toggleAiContentModal, toggleAiImageModal, t]
  );

  const [flowSelectionItems] = React.useState<FlowSelectionItem[]>(() =>
    config.configureFlowSelectionItems
      ? config.configureFlowSelectionItems(defaultFlowSelectionItems)
      : defaultFlowSelectionItems
  );

  const options = React.useMemo(() => {
    return flowSelectionItems.map((item, index) => {
      switch (item.type) {
        case 'prompt': {
          const Icon = item.icon;
          return (
            <ListItemSelect
              key={item.title}
              dataHook={item.title}
              prefix={Icon ? <Icon /> : undefined}
              title={item.title}
              onSelect={() => openAiContentModal(item)}
            />
          );
        }
        case 'action': {
          const Icon = item.icon;
          return (
            <ListItemSelect
              key={item.title}
              dataHook={'dataHook' in item ? item.dataHook : item.title}
              prefix={Icon ? <Icon /> : undefined}
              title={item.title}
              onSelect={item.onClick}
            />
          );
        }
        case 'section': {
          return <ListItemSection key={item.title} title={t(item.title)} />;
        }
        case 'divider': {
          return <ListItemDivider key={`divider-${index}`} />;
        }
        default: {
          throw unreachable(item);
        }
      }
    });
  }, [flowSelectionItems, openAiContentModal, t]);

  return (
    <DropdownModal
      dataHook={AI_FLOW_SELECTION_POPOVER}
      title={t('AIPlugin_Flow_Title')}
      onCloseButtonClick={closeModal}
      minWidth={206}
      maxHeight={242}
      options={options}
    />
  );
};
