import { ListItemSection } from '@wix/design-system';
import { EditSmall, ImageSparklesSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { EditorContext, ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import type { ModalService } from './../../ricos-modals/index.js';
import type { TiptapEditor } from './../../ricos-types/index.js';
import { DropdownModal } from './../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';
import { unreachable } from './../../_shared/uncreachable.js';

import { AI_MODAL_FLOATING_MENU_POPOVER } from '../data-hooks.js';
import { defaultPromptsConfiguration } from '../prompts.js';
import type { AiPluginEditorConfig, Prompt, PromptsConfiguration } from '../types.js';
import { AI_ACTIONS_MODAL_ID } from '../types.js';

type AiActionsModalProps = {
  config: AiPluginEditorConfig;
  toggleAiContentModal: (
    editor: TiptapEditor,
    modalsService: ModalService,
    initialPrompt?: Prompt
  ) => void;
  toggleAiImageModal: (
    editor: TiptapEditor,
    modalsService: ModalService,
    convertSelectionToPrompt?: boolean
  ) => void;
  enableImageGeneration?: boolean;
};

export const AiActionsModal: React.FC<AiActionsModalProps> = ({
  toggleAiContentModal,
  toggleAiImageModal,
  enableImageGeneration,
  config,
}) => {
  const { t } = useContext(RicosContext);
  const { adapter } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext);

  const closeModal = React.useCallback(() => {
    modalService.closeModal(AI_ACTIONS_MODAL_ID);
  }, [modalService]);

  const [prompts] = React.useState<PromptsConfiguration>(() =>
    config.configurePrompts
      ? config.configurePrompts(defaultPromptsConfiguration)
      : defaultPromptsConfiguration
  );

  const openAiContentModal = React.useCallback(
    (initialPrompt?: Prompt) => {
      toggleAiContentModal(adapter.tiptapEditor, modalService, initialPrompt);
    },
    [adapter.tiptapEditor, modalService]
  );

  const openAiImageModal = React.useCallback(() => {
    toggleAiImageModal(adapter.tiptapEditor, modalService, true);
  }, [adapter.tiptapEditor, modalService]);

  const options = React.useMemo(() => {
    const writePromptItem = (
      <ListItemSelect
        key="AIPlugin_Action_WritePrompt"
        dataHook="AIPlugin_Action_WritePrompt"
        prefix={<EditSmall />}
        title={t('AIPlugin_Action_WritePrompt')}
        onSelect={() => openAiContentModal()}
      />
    );

    const imageGenerationItems = enableImageGeneration
      ? [
          <ListItemSection
            key="AIPlugin_Prompts_Section_Image"
            title={t('AIPlugin_Prompts_Section_Image')}
          />,
          <ListItemSelect
            key="AIPlugin_Action_GenerateImage"
            dataHook="AIPlugin_Action_GenerateImage"
            prefix={<ImageSparklesSmall />}
            title={t('AIPlugin_Action_GenerateImage')}
            onSelect={() => openAiImageModal()}
          />,
        ]
      : [];

    const promptItems = prompts.floatingToolbarButtonPrompts.map(prompt => {
      switch (prompt.type) {
        case 'prompt': {
          const Icon = prompt.icon;
          return (
            <ListItemSelect
              key={prompt.title}
              dataHook={prompt.title}
              prefix={Icon ? <Icon /> : undefined}
              title={t(prompt.title)}
              onSelect={() => openAiContentModal(prompt)}
            />
          );
        }
        case 'section': {
          return <ListItemSection key={prompt.title} title={t(prompt.title)} />;
        }
        default: {
          throw unreachable(prompt);
        }
      }
    });

    return [writePromptItem, ...imageGenerationItems, ...promptItems];
  }, [
    prompts.floatingToolbarButtonPrompts,
    openAiContentModal,
    openAiImageModal,
    t,
    enableImageGeneration,
  ]);

  return (
    <DropdownModal
      dataHook={AI_MODAL_FLOATING_MENU_POPOVER}
      title={t('AIPlugin_Actions_Title')}
      onCloseButtonClick={closeModal}
      minWidth={242}
      maxHeight={242}
      options={options}
    />
  );
};
