import React, { useContext } from 'react';

import { RicosContext, useDevAiRequestService } from './../../ricos-context/index.js';
import { useRequestService } from './../../_shared/request-service-provider/request-service-provider.js';

import type { ImageStyle } from '../ai-image-modal/slice/types.js';
import type { AiPluginEditorConfig } from '../types.js';

const API_ENDPOINT = 'https://www.wix-pages.com/_serverless/ricos-ai-gateway';

export type RequestPrompt =
  | { prompt: string; additionalTags?: string }
  | { promptId: string; promptParams?: Record<string, string>; additionalTags?: string }
  | { promptSlug: string; promptParams?: Record<string, string>; additionalTags?: string };

type FetchPromptResponse<R = string[]> =
  | { type: 'SUCCESS'; results: R }
  | { type: 'ERROR'; error: string }
  | { type: 'VALIDATION_ERROR'; error: string }
  | { type: 'RATE_LIMIT_ERROR'; error: string };

export type AiRequestService = {
  fetchPrompt: (prompt: RequestPrompt, content?: string) => Promise<FetchPromptResponse>;
  fetchImagePrompt: (body: {
    prompt: string;
    imageStyle: ImageStyle;
  }) => Promise<FetchPromptResponse<{ url: string; blob: Blob }>>;
  fetchPromptFromSelection: (body: { selection: string }) => Promise<FetchPromptResponse>;
};

const pluckErrorMessage = (error: unknown, fallback: string): string =>
  error !== null &&
  typeof error === 'object' &&
  'message' in error &&
  typeof error.message === 'string'
    ? (error.message as string)
    : fallback;

export const useAiRequestService = (config: AiPluginEditorConfig): AiRequestService => {
  const { t } = useContext(RicosContext);
  const { makeRequest } = useRequestService();
  const devAiRequestService = useDevAiRequestService();

  if (devAiRequestService) {
    return devAiRequestService;
  }

  const gatewayBaseUrl = config.getGatewayBaseUrl ? config.getGatewayBaseUrl() : API_ENDPOINT;
  const appDefId = config.appDefId;

  const fetchPrompt = async (prompt: RequestPrompt, content?: string) => {
    try {
      const response = await makeRequest(`${gatewayBaseUrl}/prompt`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...prompt,
          content,
          appDefId,
        }),
      });

      const results: string[] = await response.json();

      return { type: 'SUCCESS', results } as const;
    } catch (error) {
      return { type: 'ERROR', error: pluckErrorMessage(error, '') } as const;
    }
  };

  const fetchImagePrompt = async (body: { prompt: string; imageStyle: ImageStyle }) => {
    try {
      const baseUrl =
        typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
          ? 'https://editor.wix.com/_api/ricos-ai-images/v1/ai-images'
          : 'https://www.wixapis.com/ricos/v1/ai-images';
      const response = await makeRequest(`${baseUrl}/generate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          prompt: body.prompt,
          style: body.imageStyle || 'NONE',
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));

        if (errorData.details?.applicationError?.code === 'CONTENT_VALIDATION_FAILED') {
          return {
            type: 'VALIDATION_ERROR',
            error: t('AIPlugin_Error_Content_Validation_Text'),
          } as const;
        }

        if (response.status === 429) {
          return {
            type: 'RATE_LIMIT_ERROR',
            error: t('AIPlugin_Error_Rate_Limit_Text'),
          } as const;
        }

        throw new Error(errorData.message || `HTTP ${response.status}: ${response.statusText}`);
      }

      const responseData = await response.json();
      const url = responseData.image.url;

      const blob = await fetch(url).then(response => response.blob());
      const results = { url: window.URL.createObjectURL(blob), blob };

      return { type: 'SUCCESS', results } as const;
    } catch (error) {
      if (error instanceof TypeError && error.message === 'Failed to fetch') {
        return {
          type: 'RATE_LIMIT_ERROR',
          error: t('AIPlugin_Error_Rate_Limit_Text'),
        } as const;
      }
      return { type: 'ERROR', error: pluckErrorMessage(error, '') } as const;
    }
  };

  const fetchPromptFromSelection = async (body: { selection: string }) => {
    try {
      const response = await makeRequest(`${gatewayBaseUrl}/convert-text-to-prompt`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          selectedText: body.selection,
          appDefId,
        }),
      });

      const results: string[] = await response.json();

      return { type: 'SUCCESS', results } as const;
    } catch (error) {
      return { type: 'ERROR', error: pluckErrorMessage(error, '') } as const;
    }
  };

  return React.useMemo(() => {
    return {
      fetchPrompt,
      fetchImagePrompt,
      fetchPromptFromSelection,
    };
  }, [makeRequest]);
};
